'use strict';
const state = { token: null, selected: null, runs: [], onboarding: null, selectedView: 'overview' };
const $ = id => document.getElementById(id);
function clear(node){ while(node.firstChild) node.removeChild(node.firstChild); }
function text(tag, value, cls){ const el=document.createElement(tag); if(cls) el.className=cls; el.textContent=value; return el; }
function button(label, fn){ const b=document.createElement('button'); b.type='button'; b.textContent=label; b.addEventListener('click', fn); return b; }
function api(path, opts){ return fetch(path, opts).then(async r=>{ const data=await r.json(); if(!r.ok) throw new Error(data.error||'Request failed'); return data; }); }
function guarded(path, method, payload){ return api(path,{method,headers:{'Content-Type':'application/json','X-Outrider-Control-Token':state.token},body:JSON.stringify(payload)}); }
function lines(id){ return $(id).value.split('\n').map(x=>x.trim()).filter(Boolean); }
function kv(obj){ const dl=document.createElement('dl'); Object.entries(obj).forEach(([k,v])=>{ const dt=text('dt',k); const dd=text('dd',String(v===null||v===undefined?'not configured':v)); dl.append(dt,dd); }); return dl; }
function badge(v){ return text('span', v || 'unknown', 'badge '+(v||'')); }
function card(label,value){ const c=document.createElement('div'); c.className='card'; c.append(text('div',label,'muted'), text('strong',value)); return c; }
function records(items){ const box=document.createElement('div'); if(!items||!items.length){ box.append(text('p','No records.','empty')); return box;} items.forEach(item=>{ const r=document.createElement('div'); r.className='record'; r.append(kv(item)); box.append(r); }); return box; }
function labelInput(labelText, input){ const label=document.createElement('label'); label.append(text('span',labelText), input); return label; }
async function postTransition(id, body){ return guarded(`/api/runs/${id}/state/transition`,'POST',body); }
async function loadSession(){ const s=await api('/api/session'); state.token=s.control_token; state.capabilities=s.capabilities; state.onboarding=await api('/api/onboarding'); const sel=$('engagement-platform'); clear(sel); state.onboarding.platform_options.forEach(p=>{ const o=document.createElement('option'); o.value=p; o.textContent=p; sel.append(o); }); }
async function loadRuns(){ const r=await api('/api/runs'); state.runs=r.runs||[]; $('loading').hidden=true; renderHome(); }
function renderHome(){ const home=$('home-content'); clear(home); if(!state.runs.length){ home.append(text('h2','Welcome to Outrider'), text('p','Create an authorized external reconnaissance engagement and let Outrider guide you through scope, discovery, evidence review, analysis, and findings.'), button('Start a New Engagement', showWizard), button('Import Legacy Target', showImport), text('p','Use Outrider only for assets you own or are authorized to assess.','banner')); const d=document.createElement('details'); const s=document.createElement('summary'); s.textContent='Safety and technical limitations'; d.append(s,text('p','The loopback portal is unauthenticated, single-operator, unsuitable for reverse-proxy exposure or shared hosting, and onboarding performs no discovery, enrichment, state transition, evidence capture, skill execution, Claude execution, job queue, orchestration, or reporting.')); home.append(d); return; } home.append(text('h2','Your Engagements'), button('Start a New Engagement', showWizard), button('Import Legacy Target', showImport)); const cards=document.createElement('div'); cards.className='cards'; state.runs.forEach(run=>{ const c=document.createElement('article'); c.className='card'; c.append(text('h3',run.target||'Engagement'), kv({platform:run.engagement_platform||'not configured', phase:run.phase_label||run.current_state, last_activity:run.last_activity_at||'not available', health:run.health, next_action:run.next_action||'Open Engagement'})); c.append(button('Resume Engagement', ()=>selectRun(run.run_id))); cards.append(c); }); home.append(cards); }

async function loadGuide(){ if(!state.selected) return null; state.guide=await api(`/api/runs/${state.selected}/guide`); return state.guide; }
function renderProgress(progress){ const ol=document.createElement('ol'); ol.className='progress-journey'; ol.setAttribute('aria-label','Engagement progress'); (progress||[]).forEach(step=>{ const li=document.createElement('li'); li.textContent=`${step.label}: ${step.status}`; if(step.status==='current') li.setAttribute('aria-current','step'); li.className='progress-'+step.status; ol.append(li); }); return ol; }
function renderMilestones(m){ return kv({scope_valid:m.scope_valid?'yes':'no', verified_evidence:m.verified_evidence_count, analysis_requests:m.request_count, analysis_results:m.result_count, finding_candidates:m.unpromoted_candidate_count, findings:m.finding_count}); }
function renderScopeReview(guide){ const box=document.createElement('section'); box.id='guided-scope-review'; box.append(text('h3','Review Scope'), text('p','Confirm that the listed rules match your written authorization. Wildcard scope does not include the apex. Discovered assets do not expand scope.','banner')); loadDetail('scope'); const form=document.createElement('form'); form.id='guided-confirmation-form'; form.className='transition-form'; const actor=document.createElement('input'); actor.id='guided-actor'; actor.required=true; actor.value=guide.actor||''; const confirm=document.createElement('input'); confirm.type='checkbox'; confirm.id='guided-confirm'; confirm.required=true; const msg=text('p','', 'form-message'); const btn=document.createElement('button'); btn.type='submit'; btn.textContent='Confirm Scope and Continue'; form.append(text('p','Resulting phase: Scope confirmed. No discovery runs yet.'), labelInput('Actor', actor), labelInput('I confirm the scope and want to continue', confirm), btn, msg); form.addEventListener('submit', async e=>{ e.preventDefault(); if(!confirm.checked) return; try{ await guidedAction('confirm_scope', actor.value, null); msg.textContent='Scope confirmed.'; }catch(err){ msg.textContent=err.message; } }); box.append(form); return box; }
function renderGuidedAction(guide){ const action=guide.next_action||{}; const box=document.createElement('section'); box.id='next-action-card'; box.append(text('h3','Next recommended action'), text('h4',action.label||'No action'), text('p',action.description||'')); if(action.id==='review_scope') box.append(renderScopeReview(guide)); else if(action.kind==='transition'){ const form=document.createElement('form'); form.id='guided-confirmation-form'; form.className='transition-form'; const actor=document.createElement('input'); actor.required=true; actor.value=guide.actor||''; const confirm=document.createElement('input'); confirm.type='checkbox'; confirm.required=true; const msg=text('p','', 'form-message'); const btn=document.createElement('button'); btn.type='submit'; btn.textContent=action.label; form.append(text('p', action.id==='begin_discovery'?'This records the start of Discovery, does not run tools automatically, enrichment may still be disabled, and observations never expand scope.':'This records a workflow transition only.'), labelInput('Actor', actor), labelInput('I understand and want to continue', confirm), btn, msg); form.addEventListener('submit',async e=>{ e.preventDefault(); if(!confirm.checked) return; try{ await guidedAction(action.id, actor.value, null); msg.textContent='Updated.'; }catch(err){ msg.textContent=err.message; } }); box.append(form); } else if(action.target_view){ box.append(button('Open '+action.label,()=>{ $('advanced-workspace').hidden=false; loadDetail(action.target_view); })); }
 return box; }
async function guidedAction(id, actor, reason){ const g=state.guide; const data=await guarded(`/api/runs/${state.selected}/guide/actions/${id}`,'POST',{expected_state:g.current_state, expected_guide_revision:g.guide_revision, actor:actor, reason:reason, confirmed:true}); state.guide=data.guide; await loadRuns(); await renderBasicWorkspace(state.selectedRun||{}); if(!$('advanced-workspace').hidden) await loadDetail(state.selectedView||'overview'); return data; }
async function renderBasicWorkspace(run){ const guide=await loadGuide(); const s=$('engagement-summary'); clear(s); s.append(kv({target:guide.target||run.target, platform:guide.engagement_platform||run.engagement_platform||'not configured', phase:guide.phase.label, health:guide.health.status}), renderProgress(guide.progress), text('h3','Milestones'), renderMilestones(guide.milestones), renderGuidedAction(guide)); const d=document.createElement('details'); d.append(text('summary','Safety and technical details'), text('p','Guidance is derived from local run data. It performs no action, runs no discovery, captures no evidence, executes no skills, promotes no findings, and generates no report.')); s.append(d); }

function showWizard(){ $('wizard').hidden=false; $('workspace').hidden=true; $('import').hidden=true; $('engagement-target').focus(); }
function showImport(){ $('import').hidden=false; $('wizard').hidden=true; $('workspace').hidden=true; loadImportSources(); }
async function loadImportSources(){ const sel=$('import-source'); clear(sel); try{ const d=await api('/api/import/sources'); if(!(d.sources||[]).length){ const o=option('','No target folders found under '+d.base); o.disabled=true; sel.append(o); return; } d.sources.forEach(name=>sel.append(option(name))); }catch(err){ /* leave the select empty; base may be missing */ } }
async function createImport(e){ e.preventDefault(); const msg=$('import-message'); msg.textContent=''; msg.className='form-message'; try{ const res=await guarded('/api/import-target','POST',{source:$('import-source').value, target:$('import-target-domain').value, actor:$('import-actor').value, authorization_reference:$('import-auth').value, in_scope:lines('import-scope-in'), out_of_scope:lines('import-scope-out'), confirmed:$('import-confirm').checked}); const im=res.imported||{}; msg.textContent='Imported '+(im.registered||0)+' file(s) as evidence.'; msg.className='form-message success'; $('import-form').reset(); await loadRuns(); selectRun(res.run.run_id, res.run); }catch(err){ msg.textContent=err.message; msg.className='form-message error'; } }
async function materializeEngagement(){ const msg=$('materialize-message'); msg.textContent=''; msg.className='form-message'; if(!state.selected) return; try{ const res=await guarded('/api/runs/'+state.selected+'/materialize','POST',{}); msg.textContent='Materialized to '+res.path; msg.className='form-message success'; }catch(err){ msg.textContent=err.message; msg.className='form-message error'; } }
function syncScope(){ if(!$('scope-primary-target').value.trim()) $('scope-primary-target').value=$('engagement-target').value.trim(); if(!$('scope-in').value.trim()) $('scope-in').value=$('engagement-target').value.trim(); renderReview(); }
function renderReview(){ const h=$('traffic-header-name').value.trim(); const summary=$('review-summary'); clear(summary); summary.append(kv({platform:$('engagement-platform').value, target:$('engagement-target').value, operator:$('engagement-actor').value, authorization_reference:$('engagement-auth').value, traffic_header_configured:h?'configured':'not configured', in_scope:lines('scope-in').join(', '), out_of_scope:lines('scope-out').join(', ')||'none', enrichment:state.onboarding&&state.onboarding.enrichment_enabled?'enabled':'disabled'})); }
function payload(){ const name=$('traffic-header-name').value.trim(); const value=$('traffic-header-value').value.trim(); const p={target:$('engagement-target').value, actor:$('engagement-actor').value, authorization_reference:$('engagement-auth').value, engagement_platform:$('engagement-platform').value, in_scope:lines('scope-in'), out_of_scope:lines('scope-out'), confirmed:$('authorization-confirm').checked}; if(name||value) p.traffic_header={name,value}; return p; }
async function createEngagement(e){ e.preventDefault(); const msg=$('create-run-message'); msg.textContent=''; try{ const res=await guarded('/api/runs','POST',payload()); $('engagement-form').reset(); $('include-wildcard').checked=false; msg.textContent='Engagement created'; msg.className='form-message success'; await loadRuns(); selectRun(res.run.run_id, res.run); }catch(err){ msg.textContent=err.message; msg.className='form-message error'; } }
function renderTransitionForm(data){ const form=document.createElement('form'); form.id='state-transition-form'; form.className='transition-form'; form.append(text('h4','Controlled workflow-state transition'), card('Current state', data.current_state)); const msg=text('p','', 'form-message'); form.append(msg); const select=document.createElement('select'); select.id='new-state'; select.required=true; (data.allowed_transitions||[]).forEach(t=>{ const opt=text('option', t.new_state + (t.reason_required ? ' (reason required)' : '')); opt.value=t.new_state; opt.dataset.reasonRequired=String(Boolean(t.reason_required)); select.append(opt); }); const actor=document.createElement('input'); actor.id='transition-actor'; actor.required=true; actor.autocomplete='off'; const reason=document.createElement('textarea'); reason.id='transition-reason'; reason.rows=3; const confirm=document.createElement('input'); confirm.type='checkbox'; confirm.id='transition-confirm'; confirm.required=true; const submit=document.createElement('button'); submit.type='submit'; submit.textContent='Submit state transition'; form.append(labelInput('Allowed next state',select), labelInput('Actor',actor), labelInput('Reason',reason), labelInput('Confirm this append-only state transition',confirm), submit); form.addEventListener('submit', async event=>{ event.preventDefault(); state.submitting=true; try{ await postTransition(state.selected,{expected_state:data.current_state,new_state:select.value,actor:actor.value,reason:reason.value.trim()||null}); actor.value=''; reason.value=''; confirm.checked=false; msg.textContent='State transition appended.'; await loadRuns(); await loadDetail('state'); } catch(e){ msg.textContent=e.message; } finally{ state.submitting=false; } }); return form; }
function renderScopeTools(data){ state.lastScope=data; const wrap=document.createElement('div'); wrap.append(kv({scope_revision:data.scope_revision,current_state:data.current_state,editable:data.editable,edit_reason:data.edit_reason})); const check=document.createElement('form'); check.id='scope-check-form'; check.className='transition-form'; check.append(text('h4','Scope candidate check')); const cand=document.createElement('input'); cand.id='scope-check-candidate'; cand.required=true; cand.autocomplete='off'; const btn=document.createElement('button'); btn.type='submit'; btn.textContent='Check candidate'; const result=document.createElement('div'); result.id='scope-check-result'; check.append(labelInput('Candidate',cand),btn,result); check.addEventListener('submit',async e=>{ e.preventDefault(); clear(result); try{ const d=await guarded(`/api/runs/${state.selected}/scope/check`,'POST',{candidate:cand.value}); result.append(badge(d.decision), kv({normalized_candidate:d.normalized_candidate,matched_rule:d.matched_rule,matched_rule_source:d.matched_rule_source,reason:d.reason,scope_revision:d.scope_revision})); } catch(err){ result.append(text('p',err.message,'error')); } }); wrap.append(check); const edit=document.createElement('form'); edit.id='scope-replace-form'; edit.className='transition-form'; edit.append(text('h4','Full scope rule-set replacement'), text('p','This replaces in_scope and out_of_scope only. Web scope changes are allowed only while initialized.','banner')); const ins=document.createElement('textarea'); ins.id='scope-replace-in-scope'; ins.rows=5; ins.value=(data.in_scope||[]).map(r=>r.original).join('\n'); const outs=document.createElement('textarea'); outs.id='scope-replace-out-scope'; outs.rows=5; outs.value=(data.out_of_scope||[]).map(r=>r.original).join('\n'); const actor=document.createElement('input'); actor.id='scope-replace-actor'; actor.required=true; actor.autocomplete='off'; const reason=document.createElement('textarea'); reason.id='scope-replace-reason'; reason.required=true; const confirm=document.createElement('input'); confirm.type='checkbox'; confirm.id='scope-replace-confirm'; confirm.required=true; const sub=document.createElement('button'); sub.type='submit'; sub.textContent='Replace scope rules'; const msg=text('p','', 'form-message'); edit.append(labelInput('In-scope rules, one per line',ins), labelInput('Out-of-scope rules, one per line',outs), labelInput('Actor',actor), labelInput('Reason',reason), labelInput('Confirm full replacement',confirm), sub, msg); if(!data.editable){ Array.from(edit.querySelectorAll('input,textarea,button')).forEach(el=>{el.disabled=true;}); } edit.addEventListener('submit',async e=>{ e.preventDefault(); if(!confirm.checked) return; sub.disabled=true; try{ await guarded(`/api/runs/${state.selected}/scope`,'PUT',{expected_revision:data.scope_revision,actor:actor.value,reason:reason.value,in_scope:ins.value.split('\n').map(s=>s.trim()).filter(Boolean),out_of_scope:outs.value.split('\n').map(s=>s.trim()).filter(Boolean)}); actor.value=''; reason.value=''; confirm.checked=false; msg.textContent='Scope replaced.'; await loadRuns(); await loadDetail('scope'); } catch(err){ msg.textContent=err.message; await loadDetail('scope'); } finally{ sub.disabled=false; } }); wrap.append(edit); return wrap; }

function option(value, label){ const opt=document.createElement('option'); opt.value=value; opt.textContent=label||value; return opt; }
function renderActionCheck(data){ const form=document.createElement('form'); form.id='action-check-form'; form.className='transition-form'; form.append(text('h4','Action policy check'), text('p','Point-in-time policy evaluation only; no action is executed.','banner')); const action=document.createElement('select'); action.id='action-check-action-type'; action.required=true; (data.action_types||[]).forEach(a=>action.append(option(a.action_type, `${a.action_type} (${a.action_class})`))); const candidate=document.createElement('input'); candidate.id='action-check-candidate'; candidate.autocomplete='off'; const hint=text('p','', 'muted'); const result=document.createElement('div'); result.id='action-check-result'; const btn=document.createElement('button'); btn.type='submit'; btn.textContent='Check action policy'; function sync(){ const meta=(data.action_types||[]).find(a=>a.action_type===action.value); candidate.required=Boolean(meta&&meta.candidate_required); hint.textContent=candidate.required?'Candidate is required for this action type.':'Candidate may be blank for this action type.'; } action.addEventListener('change', sync); sync(); form.append(labelInput('Action type',action), labelInput('Candidate',candidate), hint, btn, result); form.addEventListener('submit', async e=>{ e.preventDefault(); clear(result); try{ const body={action_type:action.value,candidate:candidate.value.trim()||null}; const d=await guarded(`/api/runs/${state.selected}/action/check`,'POST',body); result.append(badge(d.decision), kv({action_class:d.action_class,workflow_state:d.workflow_state,normalized_candidate:d.normalized_candidate,scope_decision:d.scope_decision,matched_scope_rule:d.matched_scope_rule,approval_required:d.approval_required,matched_approval_id:d.matched_approval_id,approval_status:d.approval_status,reason:d.reason,notice:d.notice})); } catch(err){ result.append(text('p',err.message,'error')); } }); return form; }
function renderGrantForm(data){ const form=document.createElement('form'); form.id='approval-grant-form'; form.className='transition-form'; form.append(text('h4','Grant bounded approval'), text('p','Exact normalized candidate and action type matching applies. Seven days (10080 minutes) is the maximum. Approval does not execute an action, does not replace written authorization, and actor is unauthenticated attribution.','banner'), kv({approval_revision:data.approval_revision,current_state:data.current_state,grant_enabled:data.grant_enabled,grant_disabled_reason:data.grant_disabled_reason})); const action=document.createElement('select'); action.id='approval-grant-action-type'; action.required=true; (data.action_types||[]).filter(a=>a.grantable).forEach(a=>action.append(option(a.action_type, `${a.action_type} (${a.action_class})`))); const candidate=document.createElement('input'); candidate.id='approval-grant-candidate'; candidate.required=true; candidate.autocomplete='off'; const duration=document.createElement('input'); duration.id='approval-grant-duration'; duration.type='number'; duration.min='1'; duration.max=String(data.max_lifetime_minutes||10080); duration.required=true; duration.value='30'; const actor=document.createElement('input'); actor.id='approval-grant-actor'; actor.required=true; actor.autocomplete='off'; const reason=document.createElement('textarea'); reason.id='approval-grant-reason'; reason.required=true; const conditions=document.createElement('textarea'); conditions.id='approval-grant-conditions'; const confirm=document.createElement('input'); confirm.id='approval-grant-confirm'; confirm.type='checkbox'; confirm.required=true; const warn=text('p','Intrusive validation requires extra care and explicit authorization.','warning'); warn.id='intrusive-validation-warning'; function syncWarn(){ warn.hidden=action.value!=='intrusive_validation'; } action.addEventListener('change',syncWarn); syncWarn(); const btn=document.createElement('button'); btn.id='approval-grant-submit'; btn.type='submit'; btn.textContent='Grant approval'; const msg=text('p','', 'form-message'); form.append(labelInput('Approvable action type',action), warn, labelInput('Exact candidate',candidate), labelInput('Duration in minutes',duration), labelInput('Actor',actor), labelInput('Reason',reason), labelInput('Optional conditions',conditions), labelInput('Confirm bounded approval only; do not execute anything',confirm), btn, msg); if(!data.grant_enabled){ btn.disabled=true; } form.addEventListener('submit', async e=>{ e.preventDefault(); if(!confirm.checked) return; btn.disabled=true; try{ await guarded(`/api/runs/${state.selected}/approvals`,'POST',{expected_revision:data.approval_revision,expected_state:data.current_state,action_type:action.value,candidate:candidate.value,actor:actor.value,reason:reason.value,duration_minutes:Number(duration.value),conditions:conditions.value.trim()||null}); candidate.value=''; actor.value=''; reason.value=''; conditions.value=''; confirm.checked=false; msg.textContent='Approval granted.'; await loadRuns(); await loadDetail('approvals'); } catch(err){ msg.textContent=err.message; await loadDetail('approvals'); } finally{ btn.disabled=false; } }); return form; }
function renderApprovalRecords(data){ const box=document.createElement('div'); box.id='approval-records'; box.append(text('h4','Current and historical approvals')); if(!data.approvals||!data.approvals.length){ box.append(text('p','No approvals.','empty')); return box; } data.approvals.forEach(a=>{ const rec=document.createElement('div'); rec.className='record'; rec.append(kv(a)); if(a.revocable){ const form=document.createElement('form'); form.className='transition-form approval-revoke-form'; form.append(text('h5',`Revoke ${a.approval_id}`)); const actor=document.createElement('input'); actor.required=true; actor.autocomplete='off'; const reason=document.createElement('textarea'); reason.required=true; const confirm=document.createElement('input'); confirm.type='checkbox'; confirm.required=true; const btn=document.createElement('button'); btn.type='submit'; btn.textContent='Revoke approval'; const msg=text('p','', 'form-message'); form.append(labelInput('Revocation actor',actor), labelInput('Revocation reason',reason), labelInput('Confirm revocation',confirm), btn, msg); form.addEventListener('submit', async e=>{ e.preventDefault(); if(!confirm.checked) return; btn.disabled=true; try{ await guarded(`/api/runs/${state.selected}/approvals/${a.approval_id}/revoke`,'POST',{expected_revision:data.approval_revision,actor:actor.value,reason:reason.value}); actor.value=''; reason.value=''; confirm.checked=false; msg.textContent='Approval revoked.'; await loadRuns(); await loadDetail('approvals'); } catch(err){ msg.textContent=err.message; await loadDetail('approvals'); } finally{ btn.disabled=false; } }); rec.append(form); } box.append(rec); }); return box; }
function renderApprovals(data){ state.lastApprovals=data; const wrap=document.createElement('div'); wrap.append(kv({valid:data.valid,current_state:data.current_state,approval_revision:data.approval_revision,max_lifetime_minutes:data.max_lifetime_minutes,approval_count:data.approval_count,active_count:data.active_count,expired_count:data.expired_count,revoked_count:data.revoked_count}), renderActionCheck(data), renderGrantForm(data), renderApprovalRecords(data)); return wrap; }

async function refreshInventory(){ if(!state.selected) return null; state.inventory=await api(`/api/runs/${state.selected}/evidence/artifacts`); return state.inventory; }
async function verifyEvidence(evidenceId){ return guarded(`/api/runs/${state.selected}/evidence/verify`,'POST',{evidence_id:evidenceId||null}); }
function renderInventory(data){ const box=document.createElement('section'); box.id='artifact-inventory-area'; box.append(text('h4','Eligible artifact inventory'), text('p','Metadata only. No artifact contents, preview, download, edit, delete, or upload is provided.','banner')); const btn=document.createElement('button'); btn.id='refresh-inventory'; btn.type='button'; btn.textContent='Refresh inventory'; const status=text('p','', 'form-message'); const list=document.createElement('div'); list.id='artifact-inventory-list'; async function load(){ clear(list); status.textContent='Loading inventory…'; try{ const inv=await refreshInventory(); status.textContent=`${inv.counts.eligible_files} eligible files; ${inv.counts.unsafe_or_skipped_entries} skipped${inv.truncated?' (truncated)':''}.`; (inv.candidates||[]).forEach(c=>{ const rec=document.createElement('div'); rec.className='record'; rec.append(kv(c)); if(!c.registered){ const use=document.createElement('button'); use.type='button'; use.textContent='Select for registration'; use.addEventListener('click',()=>{ const input=$('evidence-relative-artifact-path'); if(input) input.value=c.relative_artifact_path; }); rec.append(use); } list.append(rec); }); } catch(err){ status.textContent=err.message; } } btn.addEventListener('click', load); box.append(btn,status,list); load(); return box; }
