function renderDetail(view,data){ const d=$('detail'); clear(d); d.append(text('h3',view[0].toUpperCase()+view.slice(1))); if(data.notice) d.append(text('p',data.notice,'banner')); if(data.errors&&data.errors.length) d.append(records(data.errors)); if(view==='overview') d.append(kv(data)); else if(view==='scope') d.append(renderScopeTools(data), text('h3','In scope'), records(data.in_scope), text('h3','Out of scope'), records(data.out_of_scope)); else if(view==='state') d.append(kv({valid:data.valid,current_state:data.current_state,event_count:data.event_count,last_transition_at:data.last_transition_at}), renderTransitionForm(data), records(data.events)); else if(view==='evidence') d.append(renderEvidence(data)); else if(view==='approvals') d.append(renderApprovals(data)); else if(view==='contracts') d.append(renderContracts(data)); else if(view==='findings') d.append(renderFindings(data)); else if(view==='enrichment') d.append(renderEnrichment(data)); else d.append(kv(data)); d.focus(); }

